export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  let initialized = false;
  let uMotor = 0.45;
  let kThrust = 20.0;
  let massEst = 0.76;

  let zVx = 0, zVy = 0, zVz = 0;
  let dWindX = 0, dVy = 0, dWindZ = 0;

  let simIntRoll = 0, simIntPitch = 0;
  let alphaLagRoll = 0, alphaLagPitch = 0;
  let zRateRoll = 0, zRatePitch = 0;
  let alphaDistRoll = 0, alphaDistPitch = 0;
  let intYaw = 0;

  let lastAction = { thrust: 0.45, roll: 0, pitch: 0, yawRate: 0 };
  let maxGateX = -3.0;
  let currentGateIdx = 0;

  return {
    step(obs) {
      const dt = 0.01;
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      if (!initialized) {
        initialized = true;
        zVx = v.x; zVy = v.y; zVz = v.z;
        zRateRoll = rates.roll; zRatePitch = rates.pitch;
      }

      if (obs.gateIndex !== currentGateIdx) {
        currentGateIdx = obs.gateIndex;
        maxGateX = p.x;
      } else if (p.x > maxGateX) {
        maxGateX = p.x;
      }

      const bodyX = Math.sin(att.pitch) * Math.cos(att.roll);
      const bodyZ = -Math.sin(att.roll);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const dirX = cy * bodyX + sy * bodyZ;
      const dirY = Math.cos(att.pitch) * Math.cos(att.roll);
      const dirZ = -sy * bodyX + cy * bodyZ;

      uMotor += (lastAction.thrust - uMotor) * (1 - Math.exp(-dt / 0.04));

      // Attitude disturbance observer
      const errRoll = lastAction.roll - att.roll;
      const errPitch = lastAction.pitch - att.pitch;
      simIntRoll = clamp(simIntRoll + errRoll * dt, -0.35, 0.35);
      simIntPitch = clamp(simIntPitch + errPitch * dt, -0.35, 0.35);
      const alphaCmdRoll = 65 * errRoll - 13.4 * rates.roll + 22 * simIntRoll;
      const alphaCmdPitch = 65 * errPitch - 13.4 * rates.pitch + 22 * simIntPitch;
      const lagAlpha = 1 - Math.exp(-dt / 0.04);
      alphaLagRoll += (alphaCmdRoll - alphaLagRoll) * lagAlpha;
      alphaLagPitch += (alphaCmdPitch - alphaLagPitch) * lagAlpha;

      const L_att = 20;
      alphaDistRoll = clamp(L_att * (rates.roll - zRateRoll), -18, 18);
      alphaDistPitch = clamp(L_att * (rates.pitch - zRatePitch), -18, 18);
      zRateRoll += (alphaLagRoll + alphaDistRoll) * dt;
      zRatePitch += (alphaLagPitch + alphaDistPitch) * dt;

      // Translational disturbance observers
      if (p.y <= 0.085) {
        zVx = v.x; zVy = v.y; zVz = v.z;
      } else {
        const ayModel = kThrust * uMotor * dirY - (0.42 / massEst) * v.y - 9.81;
        const L_y = 18;
        dVy = clamp(L_y * (v.y - zVy), -8, 8);
        zVy += (ayModel + dVy) * dt;
        if (uMotor * dirY > 0.25 && p.y < 2.85) {
          kThrust = clamp(kThrust + 0.08 * (dVy / (uMotor * dirY)) * dt, 13.5, 26.5);
          massEst = clamp(15.2 / kThrust, 0.60, 0.95);
        }

        const aSpec = Math.max(0, kThrust * uMotor + dVy / Math.max(0.5, dirY));
        const axModel = aSpec * dirX - (0.42 / massEst) * v.x;
        const azModel = aSpec * dirZ - (0.42 / massEst) * v.z;
        const L_w = 26;
        dWindX = clamp(L_w * (v.x - zVx), -12, 12);
        dWindZ = clamp(L_w * (v.z - zVz), -12, 12);
        zVx += (axModel + dWindX) * dt;
        zVz += (azModel + dWindZ) * dt;
      }

      // Navigation & Gate-Keyhole Planner
      let tx = p.x, ty = 1.05, tz = p.z;
      let vxRef = 0, vyRef = 0, vzRef = 0;
      let kpX = 5.5, kdX = 4.2;
      let kpZ = 6.5, kdZ = 4.6;
      let kpY = 6.5, kdY = 4.5;
      let landingTouchdown = false;

      const gates = [
        { x: -1.15, y: 1.05, z: -0.85 },
        { x: 0.15, y: 1.40, z: 0.25 },
        { x: 1.35, y: 1.05, z: 1.05 },
      ];

      if (obs.gateIndex < 3) {
        const g = gates[obs.gateIndex];
        const prevG = obs.gateIndex > 0 ? gates[obs.gateIndex - 1] : null;

        // If just crossed previous gate, clear its x-plane first before shifting z/y aggressively
        if (prevG && p.x < prevG.x + 0.22) {
          tx = prevG.x + 0.35;
          ty = prevG.y + 0.3 * (g.y - prevG.y);
          tz = prevG.z;
          vxRef = 0.8;
        } else {
          ty = g.y;
          tz = g.z;
          const dy = Math.abs(p.y - g.y);
          const dz = Math.abs(p.z - g.z);
          const dx = g.x - p.x;

          // Predict z and y at crossing if moving forward
          const tCross = clamp(dx / Math.max(0.35, v.x), 0.04, 0.35);
          const zPred = p.z + v.z * tCross;
          const yPred = p.y + v.y * tCross;
          const dzPred = Math.abs(zPred - g.z);
          const dyPred = Math.abs(yPred - g.y);

          // Tight z-tracking near gate
          if (Math.abs(dx) < 0.65) {
            kpZ = 8.5;
            kdZ = 5.4;
            kpY = 7.5;
            kdY = 4.8;
          }

          const alignedTight = dz < 0.020 && dzPred < 0.022 && Math.abs(v.z) < 0.16 && dy < 0.08 && dyPred < 0.09 && Math.abs(v.y) < 0.35;
          const alignedLoose = dz < 0.045 && dy < 0.12 && Math.abs(v.z) < 0.35;

          if (dx > 0.40) {
            // Far in front of gate: approach staging point at x = g.x - 0.28
            tx = g.x - 0.25;
            vxRef = clamp(1.2 * (tx - p.x), -1.2, 1.4);
          } else if (dx > 0) {
            // Close to gate plane: only cross if inside keyhole!
            if (alignedTight || (dx < 0.08 && dz < 0.025 && dy < 0.10 && v.x > 0.2)) {
              tx = g.x + 0.35;
              vxRef = 0.85;
            } else if (alignedLoose && dx > 0.18) {
              tx = g.x - 0.16;
              vxRef = 0.2;
            } else {
              // Hold short of gate plane! Do not cross while misaligned!
              tx = g.x - 0.26;
              vxRef = 0;
              kpX = 7.0;
              kdX = 5.0;
            }
          } else {
            // Past gate plane without registering: return around outside of frame
            // Outer frame half-width in y is 0.21 + 0.07 + 0.07 = 0.35, in z is 0.21 + 0.07 + 0.175 = 0.455
            if (dz < 0.50 && dy < 0.38) {
              // Move above or beside frame before going back in x
              tx = Math.max(p.x, g.x + 0.18);
              ty = g.y + 0.45;
              tz = g.z;
            } else {
              tx = g.x - 0.35;
              ty = g.y + (p.x > g.x - 0.15 ? 0.45 : 0);
              tz = g.z;
            }
          }
        }
      } else {
        // Gate 2 passed! Head to landing pad (2.05, 0, 1.65)
        const pad = obs.pad.centre;
        const prevG = gates[2];
        if (p.x < prevG.x + 0.20) {
          tx = prevG.x + 0.35;
          ty = prevG.y;
          tz = prevG.z;
          vxRef = 0.8;
        } else {
          tx = pad.x;
          tz = pad.z;
          const distH = Math.hypot(tx - p.x, tz - p.z);
          const speedH = Math.hypot(v.x, v.z);
          kpX = 6.2; kdX = 4.6;
          kpZ = 6.2; kdZ = 4.6;

          if (distH > 0.25) {
            ty = 0.55;
          } else if (distH > 0.11 || speedH > 0.28) {
            ty = 0.22;
          } else {
            ty = 0.04;
            vyRef = -0.22;
            if (p.y <= 0.092 && speedH < 0.35) {
              landingTouchdown = true;
            }
          }
        }
      }

      // Compute desired accelerations
      const ex = tx - p.x;
      const ez = tz - p.z;
      const ey = ty - p.y;

      const axDes = clamp(kpX * ex + kdX * (vxRef - v.x), -5.5, 5.5);
      const azDes = clamp(kpZ * ez + kdZ * (vzRef - v.z), -5.5, 5.5);
      const ayDes = clamp(kpY * ey + kdY * (vyRef - v.y), -4.5, 5.5);

      // Required thrust acceleration vector
      const Tx = axDes + (0.42 / massEst) * v.x - dWindX;
      const Tz = azDes + (0.42 / massEst) * v.z - dWindZ;
      const Ty = Math.max(2.5, 9.81 + ayDes + (0.42 / massEst) * v.y - dVy);

      const TbodyX = cy * Tx - sy * Tz;
      const TbodyZ = sy * Tx + cy * Tz;

      let desPitch = Math.atan2(TbodyX, Ty);
      let desRoll = -Math.atan2(TbodyZ, Math.hypot(TbodyX, Ty));

      // Attitude disturbance cancellation + lead
      let pitchCmd = desPitch - alphaDistPitch / 65 + 0.08 * (desPitch - att.pitch) - 0.02 * rates.pitch;
      let rollCmd = desRoll - alphaDistRoll / 65 + 0.08 * (desRoll - att.roll) - 0.02 * rates.roll;

      let maxTilt = 0.58;
      if (obs.gateIndex === 3 && p.y < 0.25) {
        maxTilt = 0.15;
      }
      pitchCmd = clamp(pitchCmd, -maxTilt, maxTilt);
      rollCmd = clamp(rollCmd, -maxTilt, maxTilt);

      let thrustCmd = Ty / (kThrust * Math.max(0.55, Math.cos(att.roll) * Math.cos(att.pitch)));
      if (landingTouchdown) {
        thrustCmd = 0.15;
        pitchCmd = clamp(-alphaDistPitch / 65, -0.12, 0.12);
        rollCmd = clamp(-alphaDistRoll / 65, -0.12, 0.12);
      }
      thrustCmd = clamp(thrustCmd, 0, 1);

      intYaw = clamp(intYaw + att.yaw * dt, -0.4, 0.4);
      const yawRateCmd = clamp(-4.0 * att.yaw - 0.3 * rates.yaw - 5.0 * intYaw, -2, 2);

      lastAction = { thrust: thrustCmd, roll: rollCmd, pitch: pitchCmd, yawRate: yawRateCmd };
      return lastAction;
    },
  };
}

