        targetGate = obs.gateIndex;
        phase = 'align';
        settle = 0;
        intPosX = 0;
        intPosZ = 0;
      }

      let tx = p.x, ty = 1.05, tz = p.z;
      let vxRef = 0, vyRef = 0, vzRef = 0;
      let kpX = 5.0, kdX = 4.5;
      let kpZ = 6.5, kdZ = 5.0;
      let kpY = 6.8, kdY = 4.6;
      let maxVelX = 1.6, maxVelZ = 1.6, maxVelY = 1.6;
      let landingTouchdown = false;

