          ty = prevG.y + 0.4 * (g.y - prevG.y);
          tz = prevG.z;
          vxRef = 0.75;
        } else {
          ty = g.y;
          tz = g.z;
          const dy = Math.abs(p.y - g.y);
          const dz = Math.abs(p.z - g.z);
          const dx = g.x - p.x;

          if (Math.abs(dx) < 0.60) {
            kpZ = 8.8;
            kdZ = 5.6;
            kpY = 7.5;
            kdY = 4.8;
          }

