        const pad = obs.pad.centre;
        const prevG = GATES[2];
        if (p.x < prevG.x + 0.15) {
          tx = prevG.x + 0.30;
          ty = prevG.y;
          tz = prevG.z;
          vxRef = 0.65;
        } else {
          tx = pad.x;
          tz = pad.z;
