        }
      }

      const rawEx = tx - p.x;
      const rawEz = tz - p.z;
      if (Math.abs(rawEx) < 0.25 && p.y > 0.10) intPosX = clamp(intPosX + rawEx * dt, -0.35, 0.35);
      else intPosX *= 0.95;
      if (Math.abs(rawEz) < 0.25 && p.y > 0.10) intPosZ = clamp(intPosZ + rawEz * dt, -0.35, 0.35);
      else intPosZ *= 0.95;

      const pLeadX = p.x + 0.03 * v.x;
      const pLeadZ = p.z + 0.03 * v.z;
      const vLeadX = v.x + 0.03 * aCurrX;
      const vLeadZ = v.z + 0.03 * aCurrZ;

      const ex = clamp(tx - pLeadX, -maxVelX / 1.5, maxVelX / 1.5);
      const ez = clamp(tz - pLeadZ, -maxVelZ / 1.5, maxVelZ / 1.5);
      const ey = clamp(ty - p.y, -maxVelY / 1.5, maxVelY / 1.5);

      const axDes = clamp(kpX * ex + kdX * (vxRef - vLeadX) + 3.2 * intPosX, -6.0, 6.0);
      const azDes = clamp(kpZ * ez + kdZ * (vzRef - vLeadZ) + 4.5 * intPosZ, -6.0, 6.0);
      const ayDes = clamp(kpY * ey + kdY * (vyRef - v.y), -4.5, 5.5);

      const Tx = axDes + (0.42 / massEst) * v.x - dWindX;
      const Tz = azDes + (0.42 / massEst) * v.z - dWindZ;
      const Ty = Math.max(2.5, 9.81 + ayDes + (0.42 / massEst) * v.y - dVy);

      const TbodyX = cy * Tx - sy * Tz;
      const TbodyZ = sy * Tx + cy * Tz;

      let desPitch = Math.atan2(TbodyX, Ty);
      let desRoll = -Math.atan2(TbodyZ, Math.hypot(TbodyX, Ty));

      let pitchCmd, rollCmd, yawRateCmd;

      if (knownParams && shadowState) {
        const w = knownParams.weakness;
        const wm = knownParams.weakMotor;
        const inertia = 0.006 * knownParams.mass / 0.6;
        const F = (knownParams.mass * Ty / Math.max(0.55, dirY)) / 4;
        const dF = F * w / (1 - w);
        const reqTorqueRoll = dF * 0.115 * MOTOR_Z[wm];
        const reqTorquePitch = -dF * 0.115 * MOTOR_X[wm];
        const reqTorqueYaw = dF * 0.014 * SPIN[wm];

        pitchCmd = desPitch + (reqTorquePitch / inertia - 22 * shadowState.integral.pitch) / 65 + 0.15 * (desPitch - att.pitch) - 0.025 * rates.pitch;
        rollCmd = desRoll + (reqTorqueRoll / inertia - 22 * shadowState.integral.roll) / 65 + 0.15 * (desRoll - att.roll) - 0.025 * rates.roll;
        yawRateCmd = clamp(-4.5 * att.yaw + (reqTorqueYaw / inertia) / 8, -2, 2);
      } else {
        if (p.y > 0.09) {
          intAttRoll = clamp(intAttRoll + (desRollPrev - att.roll) * dt, -0.22, 0.22);
          intAttPitch = clamp(intAttPitch + (desPitchPrev - att.pitch) * dt, -0.22, 0.22);
        }
        pitchCmd = desPitch + 0.30 * (desPitch - att.pitch) + 3.2 * intAttPitch - 0.025 * rates.pitch;
        rollCmd = desRoll + 0.30 * (desRoll - att.roll) + 3.2 * intAttRoll - 0.025 * rates.roll;
        intYaw = clamp(intYaw + att.yaw * dt, -0.4, 0.4);
        yawRateCmd = clamp(-4.0 * att.yaw - 0.3 * rates.yaw - 5.0 * intYaw, -2, 2);
      }

      let maxTilt = 0.58;
      if (obs.gateIndex === 3 && p.y < 0.20) {
        maxTilt = 0.16;
      }
      pitchCmd = clamp(pitchCmd, -maxTilt, maxTilt);
      rollCmd = clamp(rollCmd, -maxTilt, maxTilt);
      desRollPrev = clamp(desRoll, -maxTilt, maxTilt);
      desPitchPrev = clamp(desPitch, -maxTilt, maxTilt);

      let thrustCmd = Ty / (kThrust * Math.max(0.55, Math.cos(att.roll) * Math.cos(att.pitch)));
      if (landingTouchdown) {
        thrustCmd = 0.15;
        pitchCmd = clamp(pitchCmd, -0.13, 0.13);
        rollCmd = clamp(rollCmd, -0.13, 0.13);
      }
      thrustCmd = clamp(thrustCmd, 0, 1);

      lastAction = { thrust: thrustCmd, roll: rollCmd, pitch: pitchCmd, yawRate: yawRateCmd };
      return lastAction;
    },
  };
}
